<?php

// The suite's database: the instance's tables, empty.
//
// schema.sql is generated by scripts/schema.sh, which applies every schema/
// of the tree to a throwaway file and dumps what the migrations end at. The
// dump is the schema and not the history, because a fixture has none to
// replay, and it sits in this directory because a test tree resolves every
// path inside its own root and cannot reach ../../schema.
//
// The driver takes the whole file at once: it parses the statements itself, so
// nothing here splits them and a semicolon inside a literal survives.
//
// Nothing is seeded. One connection serves every fixture and fixtures run in
// parallel, so a fixture inserts the rows it is about under IDs of its own and
// never deletes by table.

$db = new \Database(\Task\DB::NAME);

$db->query(file_get_contents("tests/schema.sql"));
